CREATE TABLE libraries_next(id TEXT PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL,path_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('movies','shows','music','photos','books','audiobooks')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,options_json TEXT NOT NULL DEFAULT '{}',last_scan_at TEXT,next_scan_at TEXT);
INSERT INTO libraries_next SELECT id,name,path,path_key,kind,is_demo,created_at,enabled,revision,options_json,last_scan_at,next_scan_at FROM libraries;
DROP TABLE libraries;
ALTER TABLE libraries_next RENAME TO libraries;
CREATE TABLE shelf_assets(id TEXT PRIMARY KEY,library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,relative_path TEXT NOT NULL,path_key TEXT NOT NULL,filesystem_id TEXT,title TEXT NOT NULL,search_text TEXT NOT NULL,folder TEXT NOT NULL,kind TEXT NOT NULL,mime TEXT NOT NULL,size_bytes INTEGER NOT NULL,modified_at TEXT NOT NULL,fingerprint TEXT NOT NULL,available INTEGER NOT NULL DEFAULT 1,excluded INTEGER NOT NULL DEFAULT 0,minimum_age INTEGER,blocked INTEGER NOT NULL DEFAULT 0,last_seen TEXT NOT NULL,UNIQUE(library_id,path_key));
CREATE INDEX shelf_folder ON shelf_assets(library_id,folder);
CREATE TABLE shelf_progress(user_id TEXT NOT NULL REFERENCES users(id),asset_id TEXT NOT NULL REFERENCES shelf_assets(id) ON DELETE CASCADE,fingerprint TEXT NOT NULL,position_json TEXT NOT NULL,client_id TEXT NOT NULL,sequence INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,asset_id));
CREATE TABLE shelf_favorites(user_id TEXT NOT NULL REFERENCES users(id),asset_id TEXT NOT NULL REFERENCES shelf_assets(id) ON DELETE CASCADE,PRIMARY KEY(user_id,asset_id));
CREATE TABLE podcast_feeds(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),protected_url TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',image_url TEXT,enabled INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,next_sync TEXT NOT NULL,last_error TEXT);
CREATE TABLE podcast_episodes(id TEXT PRIMARY KEY,feed_id TEXT NOT NULL REFERENCES podcast_feeds(id) ON DELETE CASCADE,episode_key TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,published_at TEXT,duration_seconds REAL,protected_url TEXT NOT NULL,url_hash TEXT NOT NULL,mime TEXT NOT NULL,size_bytes INTEGER,explicit INTEGER NOT NULL DEFAULT 0,UNIQUE(feed_id,episode_key));
CREATE TABLE podcast_progress(user_id TEXT NOT NULL REFERENCES users(id),episode_id TEXT NOT NULL REFERENCES podcast_episodes(id) ON DELETE CASCADE,position_seconds REAL NOT NULL,duration_seconds REAL,client_id TEXT NOT NULL,sequence INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,episode_id));
CREATE TABLE podcast_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),login_id TEXT NOT NULL,device_id TEXT NOT NULL,episode_id TEXT NOT NULL REFERENCES podcast_episodes(id),url_hash TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,last_seen TEXT NOT NULL);
